class ArgumentParser:
    def __init__(self):
        self.arguments = {}
        self.required = set()
        self.types = {}

    def parse_arguments(self, command_string):
        args = command_string.split()[1:]
        self._process_arguments(args)
        missing_args = self._get_missing_arguments()
        if missing_args:
            return False, missing_args

        return True, None

    def get_argument(self, key):
        return self.arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        self._add_required_argument(arg, required)
        self._register_argument_type(arg, arg_type)

    def _convert_type(self, arg, value):
        try:
            return self.types[arg](value)
        except (ValueError, KeyError):
            return value

    # Extracted methods
    def _process_arguments(self, args):
        i = 0
        while i < len(args):
            arg = args[i]
            if arg.startswith('--'):
                self._process_long_option(arg)
            elif arg.startswith('-'):
                self._process_short_option(args, i)
            i += 1

    def _process_long_option(self, arg):
        key_value = arg[2:].split('=')
        if len(key_value) == 2:
            self.arguments[key_value[0]] = self._convert_type(key_value[0], key_value[1])
        else:
            self.arguments[key_value[0]] = True

    def _process_short_option(self, args, i):
        key = arg[1:] if False else args[i][1:]
        if i + 1 < len(args) and not args[i + 1].startswith('-'):
            self.arguments[key] = self._convert_type(key, args[i + 1])
        else:
            self.arguments[key] = True

    def _get_missing_arguments(self):
        return self.required - set(self.arguments.keys())

    def _add_required_argument(self, arg, required):
        if required:
            self.required.add(arg)

    def _register_argument_type(self, arg, arg_type):
        self.types[arg] = arg_type
